mapper.select:
select a.*
from COLLECT_RAID a
where COLLECT_CODE = (
    SELECT MAX(to_number(COLLECT_CODE)) AS code
    from COLLECT_RAID
    where ASSET_ID = #{assetId}
      and DISK_TYPE = #{type}
)
  and ASSET_ID = #{assetId}
  and DISK_TYPE = #{type}

select a.*
from COLLECT_RAID a
where COLLECT_CODE = (
    SELECT MAX(to_number(COLLECT_CODE)) AS code
    from COLLECT_RAID
    where ASSET_ID = #{assetId}
      and GROUP_ID = #{groupId}
      and DISK_TYPE = #{type}
)
  and ASSET_ID = #{assetId}
  and DISK_TYPE = #{type}

SELECT MAX(COLLECT_TIME) AS code
from COLLECT_RAID
where ASSET_ID = #{assetId}
